from collections import defaultdict
N=8;ALL=(1<<N)-1
pop=lambda m:bin(m).count('1')
cuts=[]
for m in range(1<<N):
 c=ALL"'^m
 if m<=c:
  a=pop(m); cuts.append((m,a*(N-a),min(a,N-a)))
print('"'cuts',len(cuts))
def refine(part,m):
 out=[]
 for b in part:
  x=b&m;y=b&(ALL"'^m)
  if x:out.append(x)
  if y:out.append(y)
 return tuple(sorted(out))
start=(ALL,)
dp={start:{(0,())}}
for step in range(6):
 nd=defaultdict(set)
 for part, vals in dp.items():
  for m,c,a in cuts:
   q=refine(part,m)
   for cost,prof in vals:
    nc=cost+c
    if nc<=48: nd[q].add((nc,tuple(sorted(prof+(() if a==0 else (a,))))))
 dp=nd
 print(step+1,len(dp),sum(map(len,dp.values())))
target=tuple(1<<i for i in range(N))
print(sorted(dp[target]))
